_UNKNOWN_CREDITOR = frozenset({"unknown", "unknown creditor", "n/a", "na"})


def _creditor_key(creditor: str) -> str:
    """Case/whitespace-insensitive identity for a creditor name."""
    return re.sub(r"\s+", " ", (creditor or "").strip()).lower()


def is_junk_creditor_name(creditor: str) -> bool:
    name = (creditor or "").strip()
    if not name:
        return True
    if not is_plausible_creditor_line(name):
        return True
    # Bureaus emit the filler tokens in several casings ("Unknown Creditor",
    # "N/A", "unknown"); compare case-insensitively.
    if _creditor_key(name) in _UNKNOWN_CREDITOR:
        return True

